/// <summary>
/// Extension of table AgreementLineQuantityCommitmentHistory
/// </summary>
[ExtensionOf(tableStr(AgreementLineQuantityCommitmentHistory))]
final public class AVAAgreementLineQuantityCommitmentHistoryDbt_Extension
{

}

Method.Source:
/// <summary>
///    Initializes an <c>AgreementLineQuantityHistory</c> record from an <c>AgreementLineQuantity</c>
///    record.
/// </summary>
/// <param name="_lineQuantityCommitment">
///    The <c>AgreementLineQuantity</c> record.
/// </param>
public void initFromAgreementLineQuantityCommitment(AgreementLineQuantityCommitment _lineQuantityCommitment)
{
    next initFromAgreementLineQuantityCommitment(_lineQuantityCommitment);

    this.AVARestQtyCallOffItem = _lineQuantityCommitment.AVARestQtyCallOffItem;
}

/// <summary>
/// Calculates the net amount for the current <c>AgreementLineQuantityCommitment</c> record.
/// </summary>
/// <returns>
/// The net amount calculated based on quantity, unit price, and discounts.
/// </returns>
public LineAmount avaLineAmount()
{
    LineAmount lineAmount;

    lineAmount = PriceDisc::price2Amount(this.PricePerUnit,
                                            this.PriceUnit,
                                            this.LineDiscountAmount,
                                            this.CommitedQuantity,
                                            this.CommitedQuantity,
                                            0,
                                            this.LineDiscountPercent,
                                            this.avaAgreementHeader().Currency,
                                            0);

    return lineAmount;
}

/// <summary>
///    Retrieves the <c>AgreementHeaderHistory</c> record from the current <c>AgreementLineHistory</c> record.
/// </summary>
/// <param name="_forUpdate">
///    A Boolean value that indicates whether to read the record for update; optional.
/// </param>
/// <returns>
///    The <c>AgreementHeaderHistory</c> record.
/// </returns>
public AgreementHeaderHistory avaAgreementHeader(boolean _forUpdate = false)
{
    AgreementHeader avaHeader = AgreementLine::find(this.AgreementLine).agreementHeader();
    AgreementHeaderHistory avaHeaderHistory;

    select firstonly avaHeaderHistory
        where avaHeaderHistory.AgreementHeader == avaHeader.RecId
        && avaHeaderHistory.CreatedDateTime >= this.ValidFrom
        && avaHeaderHistory.CreatedDateTime <= this.ValidTo;

    return avaHeaderHistory;
}
